text:
.categories-list {
  padding: 0;
  margin: 0;
  list-style: none;
  display: inline-flex;
  flex-wrap: nowrap;
  flex-direction: row;
  gap: calc(3 * var(--space-step));
  flex: 0 1 auto;
  overflow: hidden;

  li {
    display: inline-block;
    padding: var(--space-step) calc(2 * var(--space-step));
    border-radius: var(--space-step);
    color: var(--item-text-color, var(--button-primary-text-color, currentColor));
    background: var(--item-color, var(--button-primary-background-color, transparent));
    text-overflow: ellipsis;
    overflow: hidden;
    white-space: nowrap;
  }
}
